73	RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
74	  RunResult r;
75	  if (argv.empty()) {
76	    r.spawn_failed = true;
77	    return r;
78	  }
79	
80	  int fds[2];
81	  if (pipe(fds) != 0) {
82	    r.spawn_failed = true;
83	    return r;
84	  }
85	
86	  pid_t pid = fork();
87	  if (pid < 0) {
88	    close(fds[0]);
89	    close(fds[1]);
90	    r.spawn_failed = true;
91	    return r;
92	  }
93	
94	  if (pid == 0) {  // child
95	    close(fds[0]);
96	    dup2(fds[1], STDOUT_FILENO);
97	    int devnull = open("/dev/null", O_RDWR);
98	    if (devnull >= 0) {
99	      dup2(devnull, STDIN_FILENO);
100	      dup2(devnull, STDERR_FILENO);
101	      if (devnull > 2) close(devnull);
102	    }
103	    close(fds[1]);
104	    exec_or_die(argv);
105	  }
106	
107	  // parent
108	  close(fds[1]);
109	  int rfd = fds[0];
110	  const long deadline = now_ms() + timeout_ms;
111	  char buf[4096];
112	
113	  while (true) {
114	    long remaining = deadline - now_ms();
115	    if (remaining < 0) remaining = 0;
116	    struct pollfd pfd{rfd, POLLIN, 0};
117	    int pr = poll(&pfd, 1, static_cast<int>(remaining));
118	    if (pr < 0) {
119	      if (errno == EINTR) continue;
120	      break;
121	    }
122	    if (pr == 0) {  // timed out with no data ready
123	      kill(pid, SIGKILL);
124	      r.timed_out = true;
125	      break;
126	    }
127	    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
128	      ssize_t n = read(rfd, buf, sizeof(buf));
129	      if (n > 0) {
130	        r.out.append(buf, static_cast<size_t>(n));
131	      } else if (n == 0) {
132	        break;  // EOF: child closed stdout
133	      } else {
134	        if (errno == EINTR) continue;
135	        break;
136	      }
137	    }
138	    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
139	      kill(pid, SIGKILL);
140	      r.timed_out = true;
141	      break;
142	    }
143	  }
144	
145	  close(rfd);
146	  int status = 0;
147	  waitpid(pid, &status, 0);
148	  // rc stays -1 (the default) when timed out or abnormally terminated.
149	  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
150	  return r;
151	}
